interactions.sample_code:
function rotate(T, pivot, direction) {
  if (direction === 'left') {
    let x = pivot;
    let y = child(x, 'right');
    let beta = child(y, 'left');

    mark('β moves from y.left to x.right', beta);
    setChild(x, 'right', beta);
    if (beta !== NIL) setParent(beta, x);

    let p = parent(x);
    mark('y takes x\'s old parent link', y);
    replaceChild(p, x, y);
    setParent(y, p);

    mark('x becomes y.left', x);
    setChild(y, 'left', x);
    setParent(x, y);
  } else {
    let y = pivot;
    let x = child(y, 'left');
    let beta = child(x, 'right');

    mark('β moves from x.right to y.left', beta);
    setChild(y, 'left', beta);
    if (beta !== NIL) setParent(beta, y);

    let p = parent(y);
    mark('x takes y\'s old parent link', x);
    replaceChild(p, y, x);
    setParent(x, p);

    mark('y becomes x.right', y);
    setChild(x, 'right', y);
    setParent(y, x);
  }
}

